\set generic '''Unknown'', ''Searched Address'', ''Frequent place'', ''Aliased Location'''
copy (select p.id, p.latitude, p.longitude, p.geodata ? 'external_place_id', coalesce(p.geodata->'properties'->>'name' is not null and p.geodata->'properties'->>'name' <> coalesce(p.geodata->'properties'->>'street', ''), false), count(v.id), coalesce(avg(case when v.duration >= 240 and ((extract(epoch from v.started_at) + p.longitude * 240)::bigint / 86400) <> ((extract(epoch from v.ended_at) + p.longitude * 240)::bigint / 86400) then 1 else 0 end), 0) from places p join users u on u.id = p.user_id left join visits v on v.place_id = p.id and v.status <> 2 and v.deleted_at is null where u.email = :'email' and p.name_locked_at is null and p.name not in ('Home', 'Work') and (p.name in (:generic) or (p.geodata ? 'properties' and not p.geodata ? 'overture')) and coalesce(p.geodata->'overture'->>'release', '') <> :'release' group by p.id) to stdout \g places.tsv
copy (select v.id, avg(st_y(pt.lonlat::geometry)), avg(st_x(pt.lonlat::geometry)) from visits v join users u on u.id = v.user_id join points pt on pt.visit_id = v.id where u.email = :'email' and v.place_id is null and v.deleted_at is null and v.status <> 2 and v.name in (:generic, 'Unknown Location') and v.started_at > now() - interval '14 days' group by v.id) to stdout \g visits.tsv
copy (select p.id, p.latitude, p.longitude from places p join users u on u.id = p.user_id where u.email = :'email') to stdout \g all-places.tsv
